from pathlib import Path
p=Path('tmp/pdfs/build_icms_frete_plan.py')
s=p.read_text(encoding='utf-8')
s=s.replace('Ajuste do ICMS do frete de valor em R$ para percentual, com memoria completa do calculo do valor liquido do produto.', 'Ajuste do ICMS do frete de valor em R$ para percentual, considerando o frete informado como valor unitario por ton/unidade.')
s=s.replace('Problema: o ICMS do frete deve ser informado em percentual, nao em R$. Assim, o sistema deve calcular o valor do ICMS do frete automaticamente com base no valor do frete da nota.', 'Problema: o ICMS do frete deve ser informado em percentual, nao em R$. Alem disso, o valor do frete informado na entrada deve ser interpretado como valor unitario por ton/unidade, e nao como valor total da nota.')
s=s.replace("['Frete unitario', 'O valor do frete informado na nota e tratado como frete total da nota. O sistema calcula frete por ton/unidade: frete_liquido_total / quantidade_convertida.'],", "['Frete unitario', 'O valor do frete informado na tela e o frete unitario por ton/unidade. O sistema calcula o frete bruto total multiplicando esse valor pela quantidade convertida.'],")
s=s.replace('frete_liquido_total / quantidade_convertida', 'frete_unitario_liquido')
