s=s.replace("['7', 'ICMS do frete em R$', 'valor_icms_frete = valor_frete_total * (icms_frete_perc / 100).'],", "['7', 'Frete bruto total', 'frete_bruto_total = frete_unitario_bruto * quantidade_convertida.'],\n    ['8', 'ICMS do frete em R$', 'valor_icms_frete = frete_bruto_total * (icms_frete_perc / 100).'],")
s=s.replace("['8', 'Frete liquido total', 'frete_liquido_total = valor_frete_total - valor_icms_frete.'],\n    ['9', 'Frete liquido por ton/unidade', 'frete_liquido_unitario = frete_liquido_total / quantidade_convertida.'],\n    ['10', 'Valor liquido total integrado', 'total_liquido = produto_liquido_total + frete_liquido_total.'],\n    ['11', 'Custo final unitario integrado', 'valor_unitario_liquido = total_liquido / quantidade_convertida = produto_liquido_unitario + frete_liquido_unitario.'],", "['9', 'Frete liquido total', 'frete_liquido_total = frete_bruto_total - valor_icms_frete.'],\n    ['10', 'Frete liquido por ton/unidade', 'frete_liquido_unitario = frete_liquido_total / quantidade_convertida.'],\n    ['11', 'Valor liquido total integrado', 'total_liquido = produto_liquido_total + frete_liquido_total.'],\n    ['12', 'Custo final unitario integrado', 'valor_unitario_liquido = total_liquido / quantidade_convertida = produto_liquido_unitario + frete_liquido_unitario.'],")
s=s.replace('frete total R$ 1.200,00 e ICMS do frete 12%.', 'frete unitario R$ 40,00 por ton e ICMS do frete 12%.')
s=s.replace("['ICMS do frete', '1.200,00 * 12% = R$ 144,00'],\n    ['Frete liquido total', '1.200,00 - 144,00 = R$ 1.056,00'],\n    ['Frete liquido por ton', '1.056,00 / 30 = R$ 35,20 por ton'],", "['Frete bruto total', '40,00 * 30 = R$ 1.200,00'],\n    ['ICMS do frete', '1.200,00 * 12% = R$ 144,00'],\n    ['Frete liquido total', '1.200,00 - 144,00 = R$ 1.056,00'],\n    ['Frete liquido por ton', '1.056,00 / 30 = R$ 35,20 por ton'],")
s=s.replace("['Valor do frete total', 'Maior ou igual a zero. Representa o valor total de frete da nota, nao o valor por ton digitado.'],", "['Valor do frete unitario', 'Maior ou igual a zero. Representa o valor por ton/unidade digitado na entrada.'],")
s=s.replace('O frete unitario deve ser calculado como frete liquido total dividido pela quantidade convertida em ton/unidade canonica.', 'O frete total deve ser calculado como frete unitario bruto multiplicado pela quantidade convertida; o frete liquido unitario deve descontar o ICMS percentual do frete.')
s=s.replace('Ao informar frete total e percentual de ICMS do frete, a tela deve mostrar o valor calculado do ICMS do frete em R$ no resumo.', 'Ao informar frete unitario e percentual de ICMS do frete, a tela deve mostrar frete bruto total, ICMS do frete em R$ e frete liquido unitario no resumo.')
s=s.replace('Valor do frete total', 'Valor do frete unitario')
